"""Rebuild the self-contained editable poster and presentation handout sources."""
from pathlib import Path
import base64, json, html, re, sys
ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent

def data(path, mime):
    return 'data:' + mime + ';base64,' + base64.b64encode((ROOT/path).read_bytes()).decode()
fonts = f"""@font-face{{font-family:Inter;src:url('{data('web/fonts/inter-latin.woff2','font/woff2')}');font-weight:100 900}}@font-face{{font-family:Manrope;src:url('{data('web/fonts/manrope-latin.woff2','font/woff2')}');font-weight:100 900}}"""
shot = data('docs/screenshots/harvest-workspace.png','image/png')
photo = data('web/assets/crops/canola.jpg','image/jpeg')
logo = data('web/assets/icons/brand.svg','image/svg+xml')
checkpoint = json.loads((ROOT/'docs/checkpoints/water-feasibility.json').read_text())
rows = [s for s in checkpoint['scenarios'] if s['crop']=='wheat']
bars = ''.join(f'''<div class="barrow"><span>{s['location']}</span><div class="track"><i style="width:{s['assessment']['summary']['gross_irrigation_ml_ha']['median']/4*100:.3f}%"></i></div><b>{s['assessment']['summary']['gross_irrigation_ml_ha']['median']:.2f}</b></div>''' for s in rows)
poster = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>FarmLens | Codex Builder Day showcase</title><style>
{fonts}
*{{box-sizing:border-box}}:root{{--ink:#252a26;--muted:#62665d;--yellow:#e7b83c;--ivory:#f7f4eb;--line:#dedacd;--green:#355b48;--blue:#316b83}}body{{margin:0;background:#ddd;color:var(--ink);font:14px/1.5 Inter,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}}.poster{{position:relative;width:420mm;height:297mm;overflow:hidden;background:var(--ivory)}}h1,h2,h3,p,figure{{margin:0}}h1,h2,h3{{font-family:Manrope,sans-serif}}.eyebrow{{font-size:11px;letter-spacing:1.6px;font-weight:700;text-transform:uppercase}}header{{position:absolute;left:14mm;right:14mm;top:12mm;height:36mm;display:flex;justify-content:space-between;gap:9mm}}.brand{{display:flex;align-items:center;gap:12px}}.brand img{{width:43px;height:43px}}h1{{font-size:48px;letter-spacing:-2.3px;line-height:1.1}}.pitch{{font-family:Manrope;font-size:24px;letter-spacing:-.6px;font-weight:650;margin-top:10px}}.intro{{font-size:14px;color:var(--muted);margin-top:4px}}.hero-photo{{width:88mm;height:36mm;object-fit:cover;object-position:center 63%;border-radius:3mm}}.event{{margin-left:auto;font-size:10px;letter-spacing:1.3px;text-align:right;padding-top:8px;width:28mm;font-weight:650}}.flow{{position:absolute;left:14mm;right:14mm;top:54mm;height:17mm;background:var(--ink);color:white;display:grid;grid-template-columns:repeat(4,1fr);border-radius:2.5mm;align-items:center;padding:0 6mm;gap:4mm}}.flow>div{{display:flex;align-items:center;gap:12px;font-size:14px;font-weight:550}}.num{{color:var(--yellow);font:700 21px Manrope}}.content{{position:absolute;left:14mm;right:14mm;top:78mm;display:grid;grid-template-columns:216mm 1fr;gap:10mm}}.sectionline{{display:flex;align-items:center;justify-content:space-between;margin-bottom:3mm}}.sectionline span:last-child{{font-size:10px;color:var(--muted)}}.screenshot{{display:block;width:216mm;height:auto;border:1px solid var(--line);border-radius:3mm;box-shadow:0 5px 16px #252a2612}}.caption{{font-size:10px;color:var(--muted);margin-top:2mm}}.insight{{border-top:3px solid var(--yellow);padding-top:4mm}}.insight h2{{font-size:28px;line-height:1.2;letter-spacing:-.8px;margin-top:3mm;max-width:150mm}}.lede{{font-size:14px;line-height:1.6;margin-top:3mm;max-width:151mm}}.chart{{margin-top:5mm;background:#fff;border:1px solid var(--line);padding:5mm 5mm 4mm;border-radius:3mm}}.chart h3{{font:700 15px Manrope}}.chart-note{{font-size:11px;color:var(--muted);margin-top:1mm}}.barrow{{display:grid;grid-template-columns:28mm 1fr 11mm;gap:3mm;align-items:center;font-size:12px;margin-top:4mm}}.track{{height:12px;background:#eef0e9;border-radius:3px}}.track i{{height:100%;display:block;background:var(--green);border-radius:3px}}.barrow:last-of-type .track i{{background:var(--blue)}}.barrow b{{text-align:right;font-size:14px}}.axis{{display:flex;justify-content:space-between;margin:2mm 14mm 0 31mm;font-size:9px;color:var(--muted)}}.assumptions{{font-size:11px;line-height:1.6;margin-top:3mm;color:var(--muted)}}.takeaway{{font-size:12px;font-weight:650;margin-top:3mm;border-left:3px solid var(--yellow);padding-left:3mm}}.bottom{{position:absolute;left:14mm;right:14mm;top:216mm;display:grid;grid-template-columns:1.05fr 1fr 1fr;gap:8mm}}.bottom section{{border-top:1px solid #aaa994;padding-top:3mm}}.bottom h3{{font-size:17px;margin:1mm 0 2mm;letter-spacing:-.3px}}.bottom p{{font-size:12px;line-height:1.65}}.bottom .small{{font-size:10.5px;color:var(--muted);margin-top:2mm}}.metric{{font-weight:750;color:var(--green)}}footer{{position:absolute;left:14mm;right:14mm;top:266mm;border-top:1px solid var(--line);padding-top:3mm;display:grid;grid-template-columns:1fr 116mm;gap:8mm}}.credits{{font-size:9px;line-height:1.6;color:var(--muted)}}a{{color:inherit;text-decoration:underline;text-underline-offset:2px}}.disclaimer{{font:700 15px/1.5 Manrope;align-self:center;text-align:right}}@page{{size:A3 landscape;margin:0}}@media print{{body{{background:none}}}}
</style></head><body><main class="poster" aria-label="FarmLens A3 landscape showcase poster">
<header><div><div class="brand"><img src="{logo}" alt="FarmLens brand mark"><h1>FarmLens</h1></div><p class="pitch">Your land, your climate, your best crops, with the reasons.</p><p class="intro">NSW land screening that puts crop possibilities, evidence and local questions in one view.</p></div><div class="event">CODEX<br>BUILDER DAY<br><br>PROJECT<br>SHOWCASE</div><img class="hero-photo" src="{photo}" alt="Illustrative canola field near Temora, NSW; not the selected site"></header>
<div class="flow"><div><span class="num">01</span>Choose a NSW point</div><div><span class="num">02</span>Explore or plan a season</div><div><span class="num">03</span>Inspect the reasons</div><div><span class="num">04</span>Compare a water scenario</div></div>
<div class="content"><section><div class="sectionline"><span class="eyebrow">From scattered data to a readable shortlist</span><span>Recorded custom interface · Dubbo</span></div><img class="screenshot" src="{shot}" alt="FarmLens interface with a NSW map, Dubbo climate and soil evidence, and crop candidates with screening scores"><p class="caption">15 crop profiles · factor bars · source records · plain-English explanations. A score is an index, not a success probability.</p></section>
<section class="insight"><p class="eyebrow">Demo insight / separate water pilot</p><h2>A crop score is only<br>the start of the water question.</h2><p class="lede">Compare wheat, barley and canola across ten complete historical seasons. Change the assumptions; inspect the water gap. Crop rankings stay unchanged.</p><div class="chart"><h3>Same wheat scenario. Different locations.</h3><p class="chart-note">Median estimated gross irrigation · ML/ha</p>{bars}<div class="axis"><span>0</span><span>2</span><span>4</span></div></div><p class="assumptions">May 1 sowing, 2016-2025 seasons. Illustrative inputs: 100 mm soil-water buffer; 50 mm at sowing; 80% rain infiltration and irrigation efficiency; 150-day crop duration.</p><p class="takeaway">Historical scenarios, not irrigation prescriptions. Wheat and barley match under identical default inputs.</p></section></div>
<div class="bottom"><section><p class="eyebrow">01 / Evidence & method</p><h3>Make the reasoning inspectable.</h3><p>ERA5 climate + modelled CSIRO/TERN SLGA soil + approximate FAO EcoCrop profiles. Seven weighted factors and source-linked NSW checks expose constraints.</p><p class="small">Water pilot: daily rain and FAO-56 ET0 × crop coefficients, with an editable storage balance.</p></section><section><p class="eyebrow">02 / Engineering</p><h3>Designed to show uncertainty.</h3><p>Python engine + custom web UI. Missing soil pH withholds the shortlist; absent factors stay unassessed. Cached evidence retains source status.</p><p class="small"><span class="metric">230 Python + 11 JavaScript tests</span> in the recorded pre-showcase run. Software checks are not agronomic validation.</p></section><section><p class="eyebrow">03 / Limits & next steps</p><h3>From prototype to local validation.</h3><p>Modelled inputs and illustrative water defaults are not farm measurements. No yield or profit forecasts. Scores and water estimates are uncalibrated.</p><p class="small">Next: agronomist review, measured soil-water comparisons and locally calibrated crop timing.</p></section></div>
<footer><p class="credits">Sources: <a href="https://open-meteo.com/en/docs/historical-weather-api">Open-Meteo ERA5</a> · <a href="https://esoil.io/TERNLandscapes/Public/Pages/SLGA/ProductDetails-SoilAttributes.html">CSIRO/TERN SLGA</a> (CC BY 4.0) · <a href="https://ecocrop.apps.fao.org/ecocrop/srv/en/home">FAO EcoCrop</a> · <a href="https://www.fao.org/4/x0490e/x0490e0b.htm">FAO-56</a> · linked NSW guidance.<br>Map © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a> (ODbL); boundary © ABS (CC BY 4.0). Example photo: <a href="https://commons.wikimedia.org/wiki/File:Canola_field_temora_nsw.jpg">“Canola field temora nsw.jpg”</a>, John O’Neill (edited by Fir0002), <a href="https://creativecommons.org/licenses/by-sa/3.0/">CC BY-SA 3.0</a>; cropped.<br>Evidence snapshot: 20 October 2026. Full method, credits and reproducibility notes accompany this poster in sources-and-notes.md.</p><p class="disclaimer">Indicative only.<br>Check with a local agronomist.</p></footer>
</main></body></html>'''
if '--script-only' not in sys.argv:
    (OUT/'farmlens-poster.html').write_text(poster)

segments = [('0:00-0:20', 'The question', 'Start on the prepared Dubbo Land overview.', "Hi everyone, this is **FarmLens**.\nIt starts with a question: **what could I grow on this land?**\nThere's a lot to consider, from the soil to the weather and available water.\nFarmLens brings those pieces together, so you've got a clearer place to start."), ('0:20-0:55', 'Start with the land', 'Point to the selected location, then Land snapshot; stay on Dubbo.', "**Let me show you around.**\nI've picked **Dubbo**, but you can search or choose a spot on the NSW map.\nWhen a place name is available, the app helps you recognise the area.\nFirst, this **land snapshot** shows mapped land cover and estimated soil conditions.\nThe cover label comes from satellite mapping for **2025**.\nIt's a first look at the location, rather than a farm inspection."), ('0:55-1:20', 'Put the weather in context', 'Point to Seven-day weather; briefly expand Seasonal climate, then scroll down.', "**Next, let's look at the weather.**\nHere's the **seven-day forecast**, with daily rain and temperatures.\nAnd here are the **seasonal patterns**, showing longer-term rainfall and temperature.\nThat helps separate what's coming this week from what's typical across the year.\nYou can check the dates and sources as you go."), ('1:20-1:50', 'Explore the crop options', 'Scroll to Explore crop options; open one candidate, then close it.', "**With that picture in mind, we can explore crop options.**\nChoose whether you're exploring the land or thinking about a planting month.\nThen open a crop to see **why it appears**, and what needs checking.\nThe score helps compare options, but it doesn't guarantee success.\nThe aim is to give you better questions to take to a local expert."), ('1:50-2:30', 'Ask about water', 'Open the prepared Wheat / May water result; point to assumptions and the poster chart.', "**One of those questions is: would there be enough water?**\nThis separate tool compares **ten past growing seasons** using assumptions you can change.\nHere, the same wheat setup shows a bigger water gap at **Broken Hill** than Dubbo.\nYou can explore how soil-water storage and crop timing affect the result.\nThe starting values are examples, rather than measurements from the selected farm.\nIt's historical context alongside the crop shortlist, and doesn't change its rankings."), ('2:30-3:00', 'Close with the purpose', 'Return to Land overview or the poster; keep the disclaimer visible.', "**So, what's next for FarmLens?**\nThe prototype now connects the land snapshot, weather, crop choices and water questions.\nThere are **automated checks**, and the next step is feedback from agronomists.\nI'd also like to compare the results with real farm measurements.\nThe goal is a **clearer starting point**, with reasons you can follow.\n**Indicative only.**\n**Check with a local agronomist.**")]
short = "Hi everyone, I'm **Mike**, a **Master of Data Science student at UTS**.\nFor today's **six-hour build**, I'm creating **FarmLens**.\nIt's for **NSW farmers and landowners** exploring what crops could suit their land.\nWeather, soil and crop information is scattered, making it hard to know where to start.\nFarmLens brings it together and explains **why each crop appears**.\n**Let me show you.**\nHere's **Dubbo**, with a land snapshot and the weather outlook.\nScrolling down, I can explore crop options and open one to see **the reasons**.\nThere's also a water tool to explore different assumptions.\nThe goal is a **clearer starting point** for local advice.\n**Indicative only.**\n**Check with a local agronomist.**\n**Thank you!**"
md = '''# FarmLens | Codex Builder Day\n\nLandscape showcase; three minutes total, including demo actions. A3 is the chosen print default, not an event requirement. This is a spoken pitch and demo run sheet, not a slide deck.\n\n## Three-minute presentation\n\nUse the bold phrases as memory cues, not words you have to recite exactly. Each spoken sentence starts on its own line. Pause briefly for the clicks; timings are rehearsal targets. If a request takes more than five seconds, use the recorded screenshot.\n\n**Remember the flow:** Question → Land snapshot → Weather → Crop options → Water → Next steps.\n\n'''
for timing,title,cue,speech in segments:
    md+=f'### {timing} | {title}\n\n**On screen:** {cue}\n\n{speech.replace(chr(10), '  '+chr(10))}\n\n'
md+='''## 60-second version\n\n**0:00-0:12:** introduce yourself and the six-hour build. **0:12-0:30:** explain the intended users and their problem. **0:30-0:52:** show the prepared Dubbo overview, scroll to crop options and open one crop. **0:52-1:00:** close and thank the audience. Keep water as a verbal mention; use screenshots if clicks are slow.\n\n'''+short.replace(chr(10), '  '+chr(10))+'''\n\n## Demo preparation and recovery\n\n- Use the custom interface at http://127.0.0.1:8503/. The retained Streamlit alternative is on 8502; the script uses custom-UI labels.\n- Before presenting, choose Dubbo, enable **Cached data only** in **Scenario help & data options**, choose **Explore my land**, **Rainfed**, **All crops**, and drainage **Unknown**. Existing map assets/tiles may still need internet on a cold load.\n- Start at **Land overview** with **Land snapshot** and **Seven-day weather** visible. Briefly expand **Seasonal climate**, then scroll to **Explore crop options**.\n- Open **Assess seasonal water · 3-crop pilot** or **Water feasibility**. Select **Wheat**, **May** and **Reset illustrative assumptions**. Confirm 100 mm buffer, 50 mm starting water, 80% infiltration, 80% efficiency and stages 20 / 30 / 60 / 40 days. Click **Calculate water scenario**, then collapse the panel until its cue.\n- Keep the prepared result at Dubbo. Show Broken Hill from the poster chart, rather than spending the three-minute slot fetching another location. Location changes reset water assumptions.\n- The recorded Dubbo example is 255 mm median demand, 60 mm additional net water and 0.75 ML/ha estimated gross irrigation. The 0.00-2.65 ML/ha interval is the historical 10th-90th percentile sample range, not a forecast interval. It is an estimate to cover the modelled gap, not supplied irrigation in the rainfed case.\n- If time slips, skip opening the profile and point to the screenshot. If data are unavailable or differ, state the source status and use the labelled recorded example; do not present saved values as a new live result.\n- Do not wait on optional OpenAI or FIRMS credentials. Rule-based explanations are available; credentialed live calls are not part of this demo.\n\n## Screenshot fallback\n\nUse the existing files without editing them:\n\n1. `../screenshots/land-overview.png` - current recorded land snapshot, seven-day weather and seasonal-climate entry.\n2. `../screenshots/pin-place-name.png` - clicked map point with a nearby locality label; use as an optional backup.\n3. `../screenshots/harvest-workspace.png` - earlier crop shortlist layout; use for the crop cards only.\n4. `../screenshots/crop-profile-assets.png` - recorded profile; note that the photo is an example crop, not the selected site.\n5. `../screenshots/water-feasibility.png` - recorded Dubbo wheat / May water result.\n\nThese are recorded views; the older profile and water screenshots predate the Land overview layout. Place-name lookup is now implemented and fixture-tested. It gives nearby locality context, not a confirmed farm address, and leaves the selected analysis coordinates unchanged. Keep Dubbo selected during the timed demo; use the saved pin-name image if you want to show this feature without loading a new point.\n\n## Short answers for questions\n\n- **Is the land snapshot current farm health?** No. Land cover is a 2025 satellite classification at a 30 m pixel; soil is modelled. Land cover is context and does not affect crop scores.\n- **Does the forecast choose the crops?** No. The seven-day outlook is context; rankings use historical climate. Seasonal charts show historical monthly averages.\n- **Does the place label identify my property?** No. It is a nearby locality or area label; the selected point remains unchanged.\n- **Is this trained machine learning?** No. Recommendations use explicit environmental ranges, weights and eligibility checks. Optional generated wording does not choose the crop ranking.\n- **What does the score mean?** A provisional screening index, not a probability, yield forecast or profit estimate. Missing factors are handled explicitly.\n- **Is the soil measured on this farm?** No. SLGA is a modelled grid. Local soil testing and agronomic interpretation are still needed.\n- **Why do wheat and barley match?** Their water profiles intentionally share generic coefficients and stage lengths; this pilot does not distinguish cultivars.\n- **Does the water result change the shortlist?** No. The pilot is separate, and its three crops remain available even if absent from the shortlist.\n- **What was validated?** Recorded software tests and source fetches. Neither calibrated crop accuracy nor farm irrigation prescriptions have been established.\n\nSee `sources-and-notes.md` for the evidence ledger, photo/map credits and production notes.\n\nIndicative only. Check with a local agronomist.\n'''
(OUT/'presentation-demo-script.md').write_text(md)

style=fonts+'''*{box-sizing:border-box}body{margin:0;color:#252a26;background:#ddd;font:11pt/1.55 Inter,sans-serif}h1,h2,h3,p{margin:0}h1,h2,h3{font-family:Manrope}h1{font-size:25pt;letter-spacing:-.8pt}h2{font-size:17pt;margin-bottom:5mm}h3{font-size:12pt}.page{position:relative;width:210mm;height:297mm;padding:18mm 18mm 20mm;background:#f7f4eb;break-after:page}.page:last-child{break-after:auto}.tag{font-size:8pt;letter-spacing:1.2pt;font-weight:700;color:#62665d}.sub{font-size:10pt;color:#62665d;margin:3mm 0 7mm}.segment{border-top:1px solid #dedacd;padding-top:4mm;margin-top:4mm}.cue{font-size:9pt;color:#316b83;margin:2mm 0}.speech{font-size:11pt;line-height:1.65}.spoken-line{font-size:10.5pt;line-height:1.55;margin:0 0 2.3mm;white-space:nowrap}.spoken-line strong{font-weight:750;color:#355b48}.segment{padding-top:3mm;margin-top:3mm}.cue{font-size:8pt;margin:2mm 0 3mm}.foot{position:absolute;left:18mm;right:18mm;bottom:12mm;font-size:8pt;color:#62665d;display:flex;justify-content:space-between;border-top:1px solid #dedacd;padding-top:3mm}.callout{padding:5mm;border-left:3px solid #e7b83c;background:white;margin:5mm 0}li{margin:2mm 0}a{color:#316b83}.notes{font-size:10pt;line-height:1.6}@page{size:A4;margin:0}@media print{body{background:none}}'''
def footer(n): return f'<footer class="foot"><span>FarmLens · Codex Builder Day · 20 October 2026</span><span>{n} / 3</span></footer>'
def section(seg):
    timing,title,cue,speech=seg
    lines=''.join('<p class="spoken-line">'+re.sub(r'\*\*(.*?)\*\*',r'<strong>\1</strong>',html.escape(line))+'</p>' for line in speech.splitlines())
    return f'<section class="segment"><h3>{timing} / {title}</h3><p class="cue">ON SCREEN: {cue}</p>{lines}</section>'
handout=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>FarmLens presentation and demo script</title><style>{style}</style></head><body>
<main><article class="page"><p class="tag">PRESENTER COPY / 3 MINUTES INCLUDING DEMO</p><h1>FarmLens</h1><p class="sub">Your land, your climate, your best crops, with the reasons.<br>Follow the bold cues and use your own words.<br>QUESTION → LAND → WEATHER → CROPS → WATER → NEXT STEPS</p>{''.join(section(s) for s in segments[:3])}<div class="callout notes"><b>Before the timer:</b> prepare Dubbo and the Wheat / May water result.<br>Full setup and fallback instructions are in the editable script.</div>{footer(1)}</article>
<article class="page"><p class="tag">PRESENTER COPY / CONTINUED</p><h2>Crop options, water and the next step</h2>{''.join(section(s) for s in segments[3:])}<p class="cue" style="margin-top:5mm">If a request takes over five seconds, switch to the recorded screenshot and name it as a saved example. Use the poster for Broken Hill.</p>{footer(2)}</article>
<article class="page"><p class="tag">BACKUP / QUICK REFERENCE</p><h2 style="margin-top:3mm">The 60-second version</h2><p class="cue">0-12s: Mike + build · 12-30s: users + problem · 30-52s: Dubbo + crop · 52-60s: close</p>{''.join('<p class="spoken-line">'+re.sub(r'\*\*(.*?)\*\*',r'<strong>\1</strong>',html.escape(line))+'</p>' for line in short.splitlines())}<section class="segment"><h3>Demo facts to keep beside you</h3><ul class="notes"><li>Dubbo wheat / May: 255 mm median demand; 60 mm additional net water; 0.75 ML/ha median gross irrigation.</li><li>Defaults: 100 mm buffer, 50 mm starting water, 80% rain infiltration, 80% irrigation efficiency, 150 crop days.</li><li>Land cover: 2025 satellite context, 30 m pixel. Seven-day weather is forecast; seasonal charts are historical. Neither land cover nor the water pilot changes rankings.</li><li>Missing pH withholds the shortlist. OpenAI and FIRMS credentialed live responses are outside this demo.</li></ul></section><section class="segment"><h3>Fallback and evidence</h3><p class="notes">Use the recorded land-overview, pin-place-name, crop-profile-assets and water-feasibility screenshots under docs/screenshots. These are recorded views. Full demo setup, Q&amp;A, source links and licences are in the accompanying Markdown script and sources-and-notes.md.</p></section><div class="callout"><b>Indicative only. Check with a local agronomist.</b></div>{footer(3)}</article></main></body></html>'''
(OUT/'presentation-demo-script.html').write_text(handout)
print('Wrote script Markdown and three-page handout HTML; poster generated only when requested.')
print('Three-minute spoken words:',sum(len(s[3].split()) for s in segments))
print('60-second spoken words:',len(short.split()))
